param(
  [int]$Port = 1111,
  [switch]$NoOpen
)

$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$OutputEncoding = [System.Text.Encoding]::UTF8

function Test-PortInUse {
  param([int]$Candidate)

  $client = New-Object System.Net.Sockets.TcpClient
  try {
    $async = $client.BeginConnect('127.0.0.1', $Candidate, $null, $null)
    if (-not $async.AsyncWaitHandle.WaitOne(300, $false)) {
      return $false
    }
    $client.EndConnect($async)
    return $true
  } catch {
    return $false
  } finally {
    $client.Close()
  }
}

function Get-AvailablePort {
  param([int]$PreferredPort)

  foreach ($candidate in $PreferredPort..($PreferredPort + 20)) {
    if (-not (Test-PortInUse -Candidate $candidate)) {
      return $candidate
    }
  }
  throw "No available port found starting from $PreferredPort."
}

function Start-DetectedBackend {
  param([string]$BackendDir)

  if (-not (Test-Path -LiteralPath $BackendDir)) {
    Write-Host '[info] No backend project found. Starting frontend demo only.' -ForegroundColor Yellow
    return
  }

  $backendPackage = Join-Path $BackendDir 'package.json'
  if (Test-Path -LiteralPath $backendPackage) {
    $package = Get-Content -Raw -LiteralPath $backendPackage | ConvertFrom-Json
    $command = if ($package.scripts.dev) { 'npm run dev' } elseif ($package.scripts.start) { 'npm start' } else { $null }
    if ($command) {
      Write-Host "[info] Starting detected Node backend: $command" -ForegroundColor Yellow
      Start-Process powershell -WindowStyle Hidden -ArgumentList @(
        '-NoProfile',
        '-ExecutionPolicy', 'Bypass',
        '-NoExit',
        '-Command',
        "Set-Location -LiteralPath '$BackendDir'; $command"
      )
      return
    }
  }

  if (Test-Path -LiteralPath (Join-Path $BackendDir 'pom.xml')) {
    Write-Host '[warn] Java backend detected but no safe one-click command is configured.' -ForegroundColor Yellow
    return
  }

  Write-Host '[warn] Backend directory exists but startup command is unknown.' -ForegroundColor Yellow
}

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$ProjectDir = Resolve-Path (Join-Path $ScriptDir '..')
$RepoDir = Resolve-Path (Join-Path $ProjectDir '..')

Set-Location $ProjectDir

if (-not (Test-Path -LiteralPath (Join-Path $ProjectDir 'node_modules'))) {
  Write-Host '[info] Installing frontend dependencies...' -ForegroundColor Yellow
  npm install
}

$ResolvedPort = Get-AvailablePort -PreferredPort $Port
$Url = "http://127.0.0.1:$ResolvedPort/"

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' AoQin Reserve & Production Planning Demo' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host "URL: $Url" -ForegroundColor Green
if ($ResolvedPort -ne $Port) {
  Write-Host "Port $Port is busy. Switched to $ResolvedPort." -ForegroundColor Yellow
}

Start-DetectedBackend -BackendDir (Join-Path $RepoDir 'backend')

if (-not $NoOpen) {
  Start-Job -ScriptBlock {
    param($TargetUrl)
    for ($attempt = 0; $attempt -lt 30; $attempt++) {
      try {
        $response = Invoke-WebRequest -Uri $TargetUrl -UseBasicParsing -TimeoutSec 2
        if ($response.StatusCode -ge 200 -and $response.StatusCode -lt 400) {
          Start-Process $TargetUrl
          return
        }
      } catch {
        Start-Sleep -Seconds 1
      }
    }
    Write-Warning "Timed out waiting for $TargetUrl"
  } -ArgumentList $Url | Out-Null
}

Write-Host ''
Write-Host 'Starting Vite dev server. Press Ctrl+C to stop.' -ForegroundColor Green
Write-Host ''

npm run dev -- --host 127.0.0.1 --port $ResolvedPort --strictPort
